<?php declare(strict_types=1);namespace App\Core;final class Csrf{public static function token():string{$u=Session::get('_csrf');if(!is_string($u)||strlen($u)<32){$u=bin2hex(random_bytes(32));Session::set('_csrf',$u);}return $u;}public static function validate(?string $B):bool{$x=Session::get('_csrf');return is_string($x)&&is_string($B)&&hash_equals($x,$B);}public static function check(Request $r):bool{if(!in_array($r->method,['POST','PUT','PATCH','DELETE'],true)){return true;}$f=$r->body['_csrf']??$r->header('x-csrf-token');if($r->isJson()&&$f===null){$f=$r->json()['_csrf']??null;}return self::validate(is_string($f)?$f:null);}}